{"tool": "write", "path": "tests/test_export_csv.py", "content": "import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic_header_and_rows(self):
        out = export_csv(
            [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}],
            ["a", "b"],
        )
        self.assertEqual(out, "a,b\r\n1,x\r\n2,y\r\n")

    def test_quoting_and_doubling(self):
        out = export_csv([{"a": 'he said "hi"', "b": "c,d"}], ["a", "b"])
        self.assertEqual(out, 'a,b\r\n"he said ""hi""","c,d"\r\n')

    def test_embedded_newlines_preserved(self):
        out = export_csv([{"a": "line1\nline2\rline3"}], ["a"])
        self.assertEqual(out, 'a\r\n"line1\nline2\rline3"\r\n')

    def test_missing_and_none_fields_empty(self):
        out = export_csv([{"a": None}, {}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n,\r\n,\r\n")

    def test_ignore_unselected_fields(self):
        out = export_csv([{"a": 1, "zzz": "hidden"}], ["a"])
        self.assertEqual(out, "a\r\n1\r\n")

    def test_non_string_values_become_str(self):
        out = export_csv([{"a": 3.5, "b": True}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n3.5,True\r\n")

    def test_unicode_preserved(self):
        out = export_csv([{"a": "héllo \u2603"}], ["a"])
        self.assertEqual(out, "a\r\nhéllo \u2603\r\n")

    def test_one_shot_generators(self):
        def rows():
            yield {"a": 1}
            yield {"a": 2}

        def cols():
            yield "a"

        self.assertEqual(export_csv(rows(), cols()), "a\r\n1\r\n2\r\n")

    def test_empty_rows(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", 1])

    def test_does_not_mutate_inputs(self):
        rows = [{"a": 1, "b": 2}]
        cols = ["a", "b"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1, "b": 2}])
        self.assertEqual(cols, ["a", "b"])


if __name__ == "__main__":
    unittest.main()
